<script setup lang="ts">
import { ref } from 'vue'
import { useAuthStore } from '@/stores/auth'
import { requestAssistance, readAssistance, reviewAssistance, type Assistance } from './api'
import { extensionSession } from '../../session'
const auth = useAuthStore()
const caseID = ref(''), audience = ref(''), question = ref(''), reason = ref(''), busy = ref(false), error = ref(''), record = ref<Assistance | null>(null), lookup = ref('')
async function run(fn: () => Promise<void>) { if (busy.value) return; busy.value = true; error.value = ''; try { await fn() } catch (e: unknown) { const code = (e as {response?: {status?: number}}).response?.status; error.value = code === 409 ? 'This record changed. Reload and review its current version.' : code === 403 || code === 404 ? 'This case, audience or action is unavailable within your current access.' : 'The outcome is unknown. Reload the record before retrying a review.' } finally { busy.value = false } }
async function ask(kind: 'answers' | 'suggestions') { if(extensionSession.aiProcessingUnavailable)return; await run(async () => { record.value = null; record.value = await requestAssistance(caseID.value.trim(), audience.value.trim(), question.value, kind); lookup.value = record.value.id }) }
async function reload() { await run(async () => { record.value = null; record.value = await readAssistance(lookup.value.trim()) }) }
async function review(action: 'correct' | 'handoff') { await run(async () => { if (record.value) { record.value = await reviewAssistance(record.value, action, reason.value); reason.value = '' } }) }
</script>
<template><main class="ai-page"><h1>Ask Employee Relations</h1><p>Answers quote current approved sources. Suggestions require human review. A handoff request records the need for a reviewer; follow your case assignment workflow.</p><p v-if="error" role="alert">{{ error }}</p><p v-if="busy" role="status">Working… Waiting for the configured AI service.</p>
<aside v-if="extensionSession.aiProcessing" aria-label="AI processing location"><h2>AI processing location</h2><p>{{ extensionSession.aiProcessing.notice }}</p></aside><p v-if="extensionSession.aiProcessingUnavailable" role="alert">AI processing information is unavailable. Refresh your session or contact the deployment operator before submitting a new request.</p>
<form @submit.prevent="ask('answers')"><label>Case reference<input v-model="caseID" required maxlength="200" :disabled="busy" /></label><label>Knowledge audience<input v-model="audience" required maxlength="200" :disabled="busy" /></label><label>Question or factual concern<textarea v-model="question" required maxlength="4096" :disabled="busy" /></label><button :disabled="busy || extensionSession.aiProcessingUnavailable || !auth.hasExtensionPermission('ai:assist')">Find a sourced answer</button><button type="button" :disabled="busy || extensionSession.aiProcessingUnavailable || !question.trim() || !caseID.trim() || !audience.trim() || !auth.hasExtensionPermission('ai:assist')" @click="ask('suggestions')">Suggest category for human review</button></form>
<form @submit.prevent="reload"><label>Saved assistance reference<input v-model="lookup" required :disabled="busy" /></label><button :disabled="busy">Reload current record</button></form>
<section v-if="record"><h2>{{ record.kind === 'classification' ? 'Provisional category' : 'Sourced answer' }}</h2><p>Saved records show the sources used when generated. Request a new answer for current guidance.</p><p>Reference {{ record.id }} · Case {{ record.case_id }} · Revision {{ record.version }} · {{ record.status }}</p><template v-if="record.classification"><p>{{ record.classification.Label }}</p><p>{{ record.classification.Rationale }}</p><p>This suggestion has not changed the case category.</p></template><p v-else>{{ record.result.Text }}</p><article v-for="source in record.result.Citations || []" :key="source.Reference"><h3>{{ source.DocumentID }} · Revision {{ source.Version }} · Page {{ source.Page.Number }}</h3><pre>{{ source.Page.Text }}</pre><p class="hash">{{ source.Reference }} · Original SHA-256 {{ source.ContentHash }}</p></article><p v-if="record.correction">Human review: {{ record.correction }}</p><form v-if="auth.hasExtensionPermission('ai:review')" @submit.prevent="review('correct')"><label>Human correction or referral reason<textarea v-model="reason" required maxlength="4096" :disabled="busy" /></label><button :disabled="busy">Save human correction</button><button type="button" :disabled="busy || !reason.trim()" @click="review('handoff')">Record human handoff request</button></form></section></main></template>
<style scoped>.ai-page{max-width:960px;margin:auto;padding:2rem}h1{font-size:1.7rem;font-weight:650}h2{font-size:1.25rem;font-weight:600}p{margin:.8rem 0}form,section{margin-top:1.5rem;padding:1.2rem;border:1px solid hsl(var(--border));border-radius:.5rem}label{display:block;margin:.7rem 0}input,textarea{display:block;width:100%;padding:.6rem;border:1px solid hsl(var(--border));background:hsl(var(--background));border-radius:.25rem}textarea{min-height:7rem}button{padding:.6rem;margin:.4rem;border:1px solid hsl(var(--border));border-radius:.25rem}button:disabled{opacity:.45}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-family:inherit}.hash{font: .8rem monospace;overflow-wrap:anywhere}article{border-top:1px solid hsl(var(--border));margin-top:1rem;padding-top:1rem}[role=alert]{color:#b91c1c}@media(max-width:650px){.ai-page{padding:1rem}}</style>
